import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { cp, mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';

const runtimeRoot = '/app/runtime';
const resultsRoot = '/results/public';
const schemaBase = 'https://flowblind.local/schemas/';
const receipts = [];
const schemaCases = [];
const regionalGoal = 'Compare reference and candidate agreement across spatial regions.';
const vectorGoal = 'Audit this planar vector field for velocity readiness and derivative evidence.';
const humanContext = {
  decisionQuestion: 'Which descriptive evidence is available?',
  nextEvidenceIntent: 'Review the resulting evidence.',
};
const regionalMetadata = {
  quantity: 'Synthetic scalar values',
  referenceMeaning: 'Analytically specified reference values.',
  candidateMeaning: 'Analytically specified candidate values.',
  coordinateUnit: 'mm',
  valueUnit: 'validation units',
  provenance: 'Synthetic fixture generated by the PR 163 review harness.',
  license: 'CC0-1.0 synthetic fixture',
};
const vectorMetadata = {
  quantity: 'Synthetic planar velocity',
  vectorMeaning: 'In-plane velocity components u and v.',
  vectorSourceKind: 'generated',
  coordinateUnit: 'mm',
  valueUnit: 'mm/s',
  timeUnit: 's',
  samplingKind: 'steady-state',
  provenance: 'Synthetic fixture generated by the PR 163 review harness.',
  license: 'CC0-1.0 synthetic fixture',
};

await mkdir(resultsRoot, { recursive: true });

async function json(path, value) {
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`);
}

async function check(id, requirement, expected, operation) {
  const receipt = { id, requirement, expected, status: 'Failed' };
  try {
    receipt.observed = await operation();
    receipt.status = 'Passed';
  } catch (error) {
    receipt.error = {
      name: error.name,
      message: error.message,
      actual: error.actual,
      expected: error.expected,
    };
  }
  receipts.push(receipt);
  console.log(`${receipt.status}: ${id}: ${receipt.error?.message ?? requirement}`);
  await json(join(resultsRoot, 'receipts.json'), receipts);
}

function regionalCsv(values) {
  const rows = ['x,y,reference_value,candidate_value'];
  for (let y = 0; y < 18; y++) {
    for (let x = 0; x < 18; x++) {
      const [reference, candidate] = values(x, y);
      rows.push(`${x},${y},${reference},${candidate}`);
    }
  }
  return `${rows.join('\n')}\n`;
}

function vectorCsv(times) {
  const rows = [times ? 'time,x,y,u,v' : 'x,y,u,v'];
  for (const time of times ?? [0]) {
    for (let y = 0; y < 6; y++) {
      for (let x = 0; x < 7; x++) {
        const values = [x, y, -y, x];
        rows.push((times ? [time, ...values] : values).join(','));
      }
    }
  }
  return `${rows.join('\n')}\n`;
}

function environment(action, goal, metadata, context, inputRoot, outputRoot) {
  const env = { ...process.env };
  for (const key of Object.keys(env)) {
    if (key.startsWith('FLOWBLIND_')) delete env[key];
  }
  Object.assign(env, {
    FLOWBLIND_TOOL_ROLE: action,
    FLOWBLIND_INPUT_ROOT: inputRoot,
    FLOWBLIND_OUTPUT_ROOT: outputRoot,
    FLOWBLIND_RESEARCH_GOAL: goal,
  });
  for (const [key, value] of Object.entries(context)) {
    const name = key.replace(/[A-Z]/g, letter => `_${letter}`).toUpperCase();
    env[`FLOWBLIND_${name}`] = String(value);
  }
  for (const [key, value] of Object.entries(metadata ?? {})) {
    const name = key.replace(/[A-Z]/g, letter => `_${letter}`).toUpperCase();
    env[`FLOWBLIND_METADATA_${name}`] = String(value);
  }
  return env;
}

async function facade(file, args, env, evidencePrefix) {
  const child = spawnSync(process.execPath, [join(runtimeRoot, file), ...args], {
    env,
    encoding: 'utf8',
    timeout: 45000,
    maxBuffer: 32 * 1024 * 1024,
  });
  await writeFile(`${evidencePrefix}.stdout`, child.stdout ?? '');
  await writeFile(`${evidencePrefix}.stderr`, child.stderr ?? '');
  await json(`${evidencePrefix}.process.json`, {
    executable: process.execPath,
    file,
    args,
    status: child.status,
    signal: child.signal,
    error: child.error?.message ?? null,
  });
  if (child.error) throw child.error;
  return child;
}

async function filesUnder(root) {
  const files = [];
  for (const entry of await readdir(root, { withFileTypes: true })) {
    const path = join(root, entry.name);
    if (entry.isDirectory()) files.push(...await filesUnder(path));
    else if (entry.isFile()) files.push(path);
  }
  return files.sort();
}

async function queueSchemas(caseId, root, prepared, run) {
  for (const [phase, output] of [['prepare', prepared], ['run', run]]) {
    if (!output) continue;
    const path = join(root, `${phase}-response.json`);
    await json(path, output);
    schemaCases.push({
      id: `${caseId}-${phase}-envelope`,
      path,
      schemaId: `${schemaBase}flowblind-catalog-research-v2-action-response.schema.json`,
      expectedValid: true,
    });
    const native = phase === 'prepare' ? output.preparation : output.result;
    const nativePath = join(root, `${phase}-native-response.json`);
    await json(nativePath, native);
    schemaCases.push({
      id: `${caseId}-${phase}-native`,
      path: nativePath,
      schemaId: `${schemaBase}flowblind-catalog-action-response-v1.schema.json`,
      expectedValid: true,
    });
  }
  for (const directory of ['prepare-output', 'run-output']) {
    for (const path of await filesUnder(join(root, directory))) {
      if (!path.endsWith('.json')) continue;
      const record = JSON.parse(await readFile(path, 'utf8'));
      if (typeof record.$schema !== 'string') continue;
      schemaCases.push({
        id: `${caseId}-${relative(root, path)}`,
        path,
        schemaId: record.$schema,
        expectedValid: true,
      });
    }
  }
  await json(join(resultsRoot, 'schema-cases.json'), schemaCases);
}

async function prepareCase(id, csv, metadata, goal = regionalGoal, context = humanContext, filename = 'candidate.csv') {
  const root = join(resultsRoot, id);
  const inputRoot = join(root, 'input');
  const outputRoot = join(root, 'prepare-output');
  await mkdir(inputRoot, { recursive: true });
  await mkdir(outputRoot, { recursive: true });
  await mkdir(join(root, 'run-output'), { recursive: true });
  await writeFile(join(inputRoot, filename), csv);
  await json(join(root, 'request.json'), { researchGoal: goal, ...context, metadata });
  const env = environment('prepare-study', goal, metadata, context, inputRoot, outputRoot);
  const process = await facade('flowblind-prepare-study-v2.mjs', [], env, join(root, 'prepare'));
  const response = JSON.parse(process.stdout);
  await json(join(root, 'prepare-response.json'), response);
  return { id, root, inputRoot, outputRoot, csv, goal, context, metadata, process, response };
}

async function completeCase(id, csv, metadata, goal = regionalGoal, context = humanContext) {
  const prepared = await prepareCase(id, csv, metadata, goal, context);
  assert.equal(prepared.process.status, 0, JSON.stringify(prepared.response));
  assert.equal(prepared.response.status, 'prepared-awaiting-confirmation');
  assert.equal(prepared.response.containsResults, false);
  const inputRoot = join(prepared.root, 'run-input');
  const outputRoot = join(prepared.root, 'run-output');
  await mkdir(inputRoot);
  await writeFile(join(inputRoot, 'candidate.csv'), csv);
  const directory = `flowblind-preparation-${prepared.response.preparedStudy.preparationArtifact.sha256}`;
  await cp(join(prepared.outputRoot, directory), join(inputRoot, directory), { recursive: true });
  const env = environment('run-and-verify-study', goal, {}, context, inputRoot, outputRoot);
  const process = await facade('flowblind-run-and-verify-study-v2.mjs', [], env, join(prepared.root, 'run'));
  const response = JSON.parse(process.stdout);
  await json(join(prepared.root, 'run-response.json'), response);
  assert.equal(process.status, 0, JSON.stringify(response));
  assert.equal(response.status, 'report-complete');
  assert.equal(response.result.verifiedStudy.deterministicReplayMatched, true);
  await queueSchemas(id, prepared.root, prepared.response, response);
  return { ...prepared, run: response, runInput: inputRoot, runOutput: outputRoot, runEnv: env };
}

let control;
await check('PUB-001', 'Identical varying regional data has zero error and unit correlation',
  'Prepare is result-free; run completes; Pearson=1, MAE=0, NRMSE=0 within 1e-12', async () => {
    control = await completeCase('regional-control', regionalCsv((x, y) => [x + 2 * y, x + 2 * y]), regionalMetadata);
    const metrics = control.run.result.verifiedStudy.result.baseline.metrics;
    for (const [endpoint, expected] of [['pearsonCorrelation', 1], ['meanAbsoluteError', 0], ['rangeNormalizedRmse', 0]]) {
      assert.equal(metrics[endpoint].status, 'available');
      assert.ok(Math.abs(metrics[endpoint].value - expected) <= 1e-12, JSON.stringify(metrics[endpoint]));
    }
    return metrics;
  });

await check('PUB-002', 'Constant regional fields do not fabricate correlation',
  'Baseline and every window report variance-zero rather than a numerical Pearson', async () => {
    const result = await completeCase('regional-constant', regionalCsv(() => [0.1, 0.3]), regionalMetadata);
    const study = result.run.result.verifiedStudy.result;
    const actual = [study.baseline.metrics.pearsonCorrelation, ...study.windows.filter(w => w.metrics).map(w => w.metrics.pearsonCorrelation)];
    await json(join(result.root, 'pearson-observed.json'), actual);
    assert.ok(actual.every(metric => metric.status !== 'available' && metric.reason === 'variance-zero'), JSON.stringify(actual));
    return actual;
  });

await check('PUB-003', 'Pearson normalization does not overflow for finite identical values',
  'Identical nonconstant x*1e80 fields have Pearson=1 within 1e-12', async () => {
    const result = await completeCase('regional-large', regionalCsv(x => [x * 1e80, x * 1e80]), regionalMetadata);
    const actual = result.run.result.verifiedStudy.result.baseline.metrics.pearsonCorrelation;
    await json(join(result.root, 'pearson-observed.json'), actual);
    assert.equal(actual.status, 'available');
    assert.ok(Math.abs(actual.value - 1) <= 1e-12, JSON.stringify(actual));
    return actual;
  });

await check('PUB-004', 'Optional human context can be omitted in the public lifecycle',
  'Preparation and execution complete; emitted artifacts are queued for separate schema validation', async () => {
    const result = await completeCase('regional-no-context', regionalCsv((x, y) => [x + y, x + y]), regionalMetadata, regionalGoal, {});
    return { status: result.run.status, humanContext: result.run.result.humanContext };
  });

await check('PUB-005', 'Vector readiness produces a normal steady-state report',
  'Rotation u=-y,v=x gives divergence=0, vorticity=2, strain=0 within 1e-12; wall shear unavailable', async () => {
    const result = await completeCase('vector-control', vectorCsv(), vectorMetadata, vectorGoal);
    const metrics = result.run.result.verifiedStudy.result.report.metrics.instantaneous;
    assert.equal(metrics.speed.status, 'available');
    assert.equal(metrics.derivatives.status, 'available');
    assert.equal(metrics.wallShear.reason, 'wall-evidence-missing');
    const spatial = metrics.derivatives.value;
    assert.ok(Math.abs(spatial.divergence.signedMean) <= 1e-12);
    assert.ok(Math.abs(spatial.vorticity.signedMeanOutOfPlane - 2) <= 1e-12);
    assert.ok(Math.abs(spatial.strainRate.mean) <= 1e-12);
    return metrics;
  });

await check('PUB-006', 'Vector lifecycle accepts omitted optional human context',
  'Prepare/run complete; output schemas checked separately', async () => {
    const result = await completeCase('vector-no-context', vectorCsv(), vectorMetadata, vectorGoal, {});
    return { status: result.run.status };
  });

await check('PUB-007', 'Frame-average data does not become instantaneous evidence',
  'Run completes with explicit temporal unavailability; all output schemas checked separately', async () => {
    const result = await completeCase('vector-frame-average', vectorCsv([0, 1, 2]), {
      ...vectorMetadata, samplingKind: 'frame-average', exposureDuration: 0.05, selectedTime: 0,
    }, vectorGoal);
    const metrics = result.run.result.verifiedStudy.result.report.metrics;
    assert.equal(metrics.instantaneous.speed.reason, 'frame-average-exposure-metadata-insufficient');
    return metrics;
  });

await check('PUB-008', 'Out-of-range requested time remains an explicit unavailable outcome',
  'Run completes with time-out-of-range; emitted schemas checked separately', async () => {
    const result = await completeCase('vector-out-of-range', vectorCsv([0, 1, 2]), {
      ...vectorMetadata, samplingKind: 'instantaneous', selectedTime: 5,
    }, vectorGoal);
    const metrics = result.run.result.verifiedStudy.result.report.metrics.instantaneous;
    assert.equal(metrics.speed.reason, 'time-out-of-range');
    return metrics;
  });

for (const [field, length] of [['license', 257], ['quantity', 257], ['vectorMeaning', 2049], ['provenance', 2049]]) {
  await check(`META-${field}`, `Advertised vector metadata bounds apply to ${field}`,
    `${length} ASCII characters, below the published 4096 limit, must prepare successfully`, async () => {
      const result = await prepareCase(`vector-long-${field}`, vectorCsv(), { ...vectorMetadata, [field]: 'x'.repeat(length) }, vectorGoal);
      schemaCases.push({
        id: `vector-long-${field}-input-contract`,
        path: join(result.root, 'request.json'),
        schemaId: `${schemaBase}flowblind-catalog-research-v2-prepare-input.schema.json`,
        expectedValid: true,
      });
      await json(join(resultsRoot, 'schema-cases.json'), schemaCases);
      assert.equal(result.process.status, 0, JSON.stringify(result.response));
      assert.equal(result.response.status, 'prepared-awaiting-confirmation');
      return { status: result.response.status, characters: length };
    });
}

for (const [id, csv, filename] of [
  ['empty-file', '', 'candidate.csv'],
  ['wrong-filename', regionalCsv((x, y) => [x + y, x + y]), 'renamed.csv'],
  ['invalid-number', regionalCsv((x, y) => [x + y, x === 0 && y === 0 ? 'NaN' : x + y]), 'candidate.csv'],
]) {
  await check(`NEG-${id}`, `Malformed attachment ${id} is refused`,
    'Nonzero exit, result-free response, no promoted preparation files', async () => {
      const result = await prepareCase(id, csv, regionalMetadata, regionalGoal, humanContext, filename);
      assert.notEqual(result.process.status, 0);
      assert.equal(result.response.containsResults, false);
      assert.equal((await filesUnder(result.outputRoot)).length, 0);
      return result.response;
    });
}

await check('NEG-private-default-off', 'Public facade does not activate the bundled private method',
  'A hidden-flow request without host-private activation remains result-free and cannot run', async () => {
    const result = await prepareCase('private-default-off', '{}\n', {}, 'Bound an unobserved hidden flow perturbation.', {}, 'problem.json');
    assert.notEqual(result.process.status, 0);
    assert.equal(result.response.status, 'unsupported');
    assert.equal(result.response.containsResults, false);
    assert.equal((await filesUnder(result.outputRoot)).length, 0);
    return result.response;
  });

await check('NEG-confirmation-authority', 'Module run cannot execute without package-issued run authority',
  'No result files; authority-unavailable / host-confirmation-authority-unavailable', async () => {
    assert.ok(control, 'Regional control case is required');
    const verifier = await import(`${runtimeRoot}/flowblind-research-teammate-verification-v2.mjs`);
    const verified = await verifier.verifyFlowBlindCatalogResearchV2Package({ toolRole: 'prepare-study' });
    const runtime = await import(`${runtimeRoot}/generated/flowblind-catalog-research-runtime-v2.mjs?sha256=${verified.lock.publicRuntime.sha256}`);
    const outputRoot = join(resultsRoot, 'without-confirmation');
    await mkdir(outputRoot);
    const response = await runtime.callCatalogResearchV2Action('run-and-verify-study', {
      researchGoal: regionalGoal, ...humanContext,
    }, { inputRoot: control.runInput, outputRoot }, verified.packageVerification);
    await json(join(resultsRoot, 'without-confirmation-response.json'), response);
    assert.equal(response.status, 'authority-unavailable');
    assert.equal(response.authority.reason, 'host-confirmation-authority-unavailable');
    assert.equal((await filesUnder(outputRoot)).length, 0);
    return response;
  });

await check('REC-001', 'Committed report is readable from a fresh process',
  'Cold resource bytes equal the HTML identity in the completed report', async () => {
    assert.ok(control, 'Regional control case is required');
    const result = await facade('flowblind-report-resource-v2.mjs', [control.run.publication.resourceUri], control.runEnv, join(control.root, 'cold-resource'));
    assert.equal(result.status, 0, result.stderr);
    const expected = control.run.result.verifiedStudy.artifacts.html;
    assert.equal(createHash('sha256').update(result.stdout).digest('hex'), expected.sha256);
    assert.match(result.stdout, /<main id="main-content">/);
    await writeFile(join(control.root, 'report-preview.html'), result.stdout);
    return { sha256: expected.sha256, bytes: Buffer.byteLength(result.stdout) };
  });

await check('REC-002', 'Re-running against a committed report does not rewrite it',
  'Same receipt/resource URI and byte-identical report files', async () => {
    assert.ok(control, 'Regional control case is required');
    const before = {};
    for (const path of await filesUnder(control.runOutput)) before[path] = createHash('sha256').update(await readFile(path)).digest('hex');
    const result = await facade('flowblind-run-and-verify-study-v2.mjs', [], control.runEnv, join(control.root, 'replay'));
    assert.equal(result.status, 0, result.stdout);
    const response = JSON.parse(result.stdout);
    assert.equal(response.publication.resourceUri, control.run.publication.resourceUri);
    const after = {};
    for (const path of await filesUnder(control.runOutput)) after[path] = createHash('sha256').update(await readFile(path)).digest('hex');
    assert.deepEqual(after, before);
    return { files: Object.keys(before).length, resourceUri: response.publication.resourceUri };
  });

await check('REC-003', 'Modified report bytes cannot pass cold verification',
  'Separate tampered report copy is rejected with a nonzero process exit', async () => {
    assert.ok(control, 'Regional control case is required');
    const outputRoot = join(control.root, 'tampered-output');
    await cp(control.runOutput, outputRoot, { recursive: true });
    const html = join(outputRoot, control.run.result.verifiedStudy.artifacts.html.reference);
    await writeFile(html, `${await readFile(html, 'utf8')}\nTAMPERED\n`);
    const result = await facade('flowblind-report-resource-v2.mjs', [control.run.publication.resourceUri], {
      ...control.runEnv, FLOWBLIND_OUTPUT_ROOT: outputRoot,
    }, join(control.root, 'tampered-resource'));
    assert.notEqual(result.status, 0);
    return { exitCode: result.status };
  });

await json(join(resultsRoot, 'schema-cases.json'), schemaCases);
await json(join(resultsRoot, 'summary.json'), {
  sourceSha: '7bc7e6af8b0d29cdf2453025c6dcaed9b435c240',
  runtime: process.version,
  total: receipts.length,
  passed: receipts.filter(receipt => receipt.status === 'Passed').length,
  failed: receipts.filter(receipt => receipt.status === 'Failed').length,
  schemaCases: schemaCases.length,
  boundaries: 'Original runtime and facades; synthetic inputs; local authority conformance is not live user confirmation or model execution.',
});
process.exitCode = receipts.some(receipt => receipt.status !== 'Passed') ? 1 : 0;
